function request(fields) {
  const body = { board: state.board, ...fields, mode: modeEl.value, level: levelEl.value };
  if (state.game) body.game = state.game;
  return body;
}

function render() {
  const winning = new Set(state.line || []);
  cells.forEach((cell, i) => {
    const mark = state.board[i];
    const stealable = stealMode && state.stealable.includes(i);
    cell.textContent = mark;
    cell.className = `cell ${mark.toLowerCase()} ${winning.has(i) ? "win" : ""} ${stealable ? "stealable" : ""}`;
    // aria-disabled, not disabled: a disabled button cannot keep the focus
    const disabled = stealMode ? !stealable : state.status !== "playing" || Boolean(mark);
    cell.setAttribute("aria-disabled", String(disabled));
    cell.tabIndex = i === focused ? 0 : -1;
    const row = Math.floor(i / 3) + 1;
    const col = (i % 3) + 1;
    const what = mark || "empty";
    const extra = `${winning.has(i) ? ", winning" : ""}${stealable ? ", can be stolen" : ""}`;
    cell.setAttribute("aria-label", `Row ${row}, column ${col}, ${what}${extra}`);
  });
  statusEl.textContent = notice || describe();
  document.getElementById("score-x").textContent = score.X;
  document.getElementById("score-o").textContent = score.O;
  document.getElementById("score-draw").textContent = score.draw;
  document.getElementById("score-help").textContent = score.help;
  cheatEl.hidden = !unlocked;
  const canSteal = state.stealable.length > 0;
  stealEl.setAttribute("aria-disabled", String(!canSteal));
  stealEl.setAttribute("aria-pressed", String(stealMode));
  if (canSteal) cheatTextEl.textContent = "Press Steal, then choose an O. Esc cancels.";
  else cheatTextEl.textContent = state.steal_used ? "Steal used" : "No O to steal yet";
}

function describe() {
  const vsComputer = modeEl.value === "computer";
  if (state.status === "won") {
    if (!vsComputer) return `${state.winner} wins!`;
